// src/components/dashboard/sales-analytics.tsx
'use client';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const data = [
  { name: '09:00 AM', sales: 50 },
  { name: '12:00 PM', sales: 150 },
  { name: '04:00 PM', sales: 120 },
  { name: '06:00 PM', sales: 230 },
  { name: '08:00 PM', sales: 90 },
  { name: '12:00 PM', sales: 180 },
];

const SalesAnalytics = () => {
  return (
    <div className="bg-white p-6 rounded-2xl mb-8">
      <div className="flex justify-between items-center mb-4">
        <h3 className="font-bold text-lg">Sales Analytics</h3>
        <a href="#" className="text-sm text-brand-text-secondary">See all</a>
      </div>
      <div style={{ width: '100%', height: 250 }}>
        <ResponsiveContainer>
          <LineChart data={data}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} />
            <XAxis dataKey="name" axisLine={false} tickLine={false} />
            <YAxis axisLine={false} tickLine={false} />
            <Tooltip />
            <Line type="monotone" dataKey="sales" stroke="#E67E22" strokeWidth={3} dot={false} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default SalesAnalytics;